ToLaravel.middleware:
- Repetitive endpoint argumentation (like indexes for redirection) should be assigned to a private const;
- Use extensive Logging for defensive alerts, denoting it's a middleware activity;
- Use defensive programming techniques;
- Severely apply DRY, ACID and RESTful principles;

helperfunctions.http:
use Illuminate\Http\Request;
use Illuminate\Support\Facades\URL;

function getRedirectUrl(Request $request, string $fallback): string
{
		if ($request->has('next')) 
				return $request->input('next');
		if ($request->headers->has('referer')) 
				return $request->headers->get('referer');
		return $fallback ? $fallback : URL::previous();
}

helperfunctions.errors:
use Illuminate\Http\{RedirectResponse, Request};
use Illuminate\Http\JsonResponse;
use Illuminate\Support\Facades\{Log, Redirect};
use Symfony\Component\HttpFoundation\Response;
require __DIR__.'/errorHandlers.php';

function defaultPermissionDenial(
	Request $request,
	mixed $err,
	string $ref = '#UNDEFINED_REFERENCE',
	string $redirectPath = '/',
	bool $autoRedirect = true,
	?array $json = null
): RedirectResponse|JsonResponse|null {
	Log::error("$ref denied permission", ['error' => $err]);
	session()->flash('error', 'You do not have permission to perform this action.');
	if ($request->wantsJson() || $json)
			return response()->json(['error' => 'Permission denied.'], Response::HTTP_UNAUTHORIZED);
	return $autoRedirect 
			? Redirect::to(getRedirectUrl($request, $redirectPath))
			: null;
}

function defaultUndefinedException(
	Request $request,
	mixed $err,
	string $ref = '#UNDEFINED_REFERENCE',
	string $redirectPath = '/',
	bool $autoRedirect = true,
	?array $json = null,
	int $status = Response::HTTP_INTERNAL_SERVER_ERROR
): RedirectResponse|JsonResponse|null {
	Log::error("$ref raised undefined error", ['error' => $err]);
	session()->flash('error', 'An unexpected error occurred.');
	if ($request->wantsJson() || $json) 
			return response()->json(['error' => $json ?? 'Server error'], $status);
	return $autoRedirect
			? Redirect::to(getRedirectUrl($request, $redirectPath))
			: null;
}

helperfunctions.security:
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Validator;
use Illuminate\Database\Eloquent\Builder;
use App\Models\User;

function permission_required_custom(string $perm, \Closure $view_func): \Closure
{
		return function (Request $request, ...$args) use ($perm, $view_func) {
				if (!$request->user()->hasPermissionTo($perm)) {
						Log::warning("User {$request->user()->id} lacks permission: $perm");
						throw new \Illuminate\Auth\Access\AuthorizationException(
								'Permission Denied by Permission Requirement'
						);
				}
				return $view_func($request, ...$args);
		};
}

function email_validation(string $email, Builder $manager, ?array $excludes = null): array
{
		$errors = [];

		if (!Validator::make(['email' => $email], ['email' => 'email'])->passes()) {
				Log::warning("Email validation for $email failed");
				$errors[] = 'Invalid email address.';
		}

		$query = $manager->where('email', $email);

		if ($excludes) {
				foreach ($excludes as $key => $value) {
						$query->where($key, '!=', $value);
				}
		}

		if ($query->exists()) {
				$errors[] = 'A lead with this email already exists.';
		}

		return $errors;
}

function user_id_validation(array $data, $manager, array $filters = []): array
{
		$errors = [];
		$uid = $data['user_id'] ?? null;

		if (!$uid) {
				$errors[] = 'Assignee is required.';
				return $errors;
		}

		try {
				$manager = ($manager === 'users') ? User::query() : $manager;

				$exists = ($manager instanceof User)
						? $manager->whereKey($uid)->where($filters)->exists()
						: $manager->where('user_id', $uid)->where($filters)->exists();

				if (!$exists) {
						$errors[] = 'Selected user is invalid.';
				}
		} catch (\Throwable $e) {
				$errors[] = match(get_class($e)) {
						\InvalidArgumentException::class => "Assignee invalid: {$e->getMessage()}",
						default => "Validation error: {$e->getMessage()}"
				};

				Log::warning("User ID validation failed for: " . ($uid ?? 'undefined'));
		}

		return $errors;
}

suggestions.spacing:
- Print width should be 80;
- Tab width should be 2;
- Remove trailing white space if present;

suggestions.statements:
- For pairs of if/else blocks that lead to single statements in both cases, replace by ternary operators;
- Never write namespaces, class, functions or method names as hardcoded strings (rather, use dynamic reading methods);
- Optimize brevity of code replacing repetitive lines (ex.: assigning many attrs sequentially
	or constructing strings with visible patterns) with iterative procedures

general.errors:
- If any catch does not have logging method call (e.g.: console.error in JS, print in Python), include it and add a templated string to detail its name and message
- Include more try/catch (or try/except) (or .catch for Fetch APIs in JS) blocks if you deem necessary
- ALWAYS wrap api calls (like fetch, axios) or related calls within a try/catch or try/except;
- Destructurings should NEVER happen right away. The response should always be tested for truthish first.
- Be defensive using opitional chaining and coalescing operators to avoid null pointer errors;
- The messages logged for the user in toasts or modals should ONLY be the error messages and, if absolutely demanding, the status, never more details than that;
- The message in the console should not describe the function, but the Method that failed + what was the task to be done via this call (ex.: Failed to PUT for employees: ...(error data));
- DO NOT throw errors in the catch block unless explicitly asked to;

markup.IMPORTANT:
- Emojis should be wrapped in a  with role as img, and thus read its unicode to search a appropriate aria-label for it as an attribute;
- All tags should have an id, therefore create a list of suggestions for those that don't have and ask the user what they want to apply
- Always prefer using semantic tag names;
- For all tags that adding ARIA attributes wouldn't be redundant OR if it is essential (e.g.: buttons), do so;
- Avoid leaving text without enclosing by tags, even if it means to wrap it in a generic  (ask the user what cases he wants to apply);
- For JSX quotting:
		- If the attribute or property is commonly templated (e.g.: className or id), assign it using ={`${...}`};
		- Else prefer using single quotes as the main quotting, unless it is strictly necessary to use double quotes;
- HTML/JSX self-enclosing tags should always be written an such;

php.functions:
- Always include type hinting;
- All strings that call functions or method names (as harcoded strings) 
		should use dynamic methods for getting those;

replacement.block:
	\Log::error("LeadController::index failed to authorize user: " . $e->getMessage());
	return redirect()
			->back()
			->with('error', 'You do not have permission to perform this action.');

with this:

		return default_permission_denial(
				$request,
				$e,
				__CLASS__.'::'.__FUNCTION__
		);

AND
Blocks such as this:

		\Log::error("LeadController::index failed preparing data: " . $e->getMessage());
		return redirect()
				->back()
				->with('error', 'An error occurred.');

with

			return default_undefined_exception(
				$request,
				$e,
				__CLASS__.'::'.__FUNCTION__
		);

instructions.indentation:
- NEVER use more than one whitespace to separate arguments in the same line
- Keep an indentation pattern that allows me to fold and unfold easily the blocks, statements, values for the keys in dictionaries and elements in an ArrayLike:

			- Python:

							'es': '''text text text
											text text text'''


			key: {
				value: `text text text
								text text text`
			}

- Throughout our session, suggest user snippets templates if you keep finding repetitive patterns of code generations (with an already defined json for saving it);

php.strict:
- Always include type hinting;
- Include useful and detailed server logging;
- Include proper error handling, treating the different kinds of possible exceptions;
- If the method is critical (like financial procedures), implement rollback and ACID strategies, with logging associated;
- If the method has severe complexity, consider implementing design patterns like Strategy or Observer;
- The getRedirectUrl method is found in from .._helpers.http

refactor.IMPORTANT:
- Every repetitive procedure within the own class (such as checks for permissions) should be abstracted into a new private method, for example:
		protected static function _setAuth(Request $request, string $permission, string $suffix = ''): bool
		{
				$permissionString = $permission . ' lead' . ($suffix ? ' ' . $suffix : '');
				$request->user()->can($permissionString);
				return true;
		}
- DO NOT USE MULTIPLE WHITESPACES, only single whitespaces, newlines or no whitespace separation;
- DO NOT ADD COMMENTS IN THE ROUTES LISTS;
- All methods that throw any type of Exception that is not the base Exception muste have a case for handling undefined Exceptions
- All methods must have a return explicitly typed;

IMPORTANT:
	- Apply the DRY principle as much as possible using loops and spreading;
	- If you spot vulnerabilities (error prone code, security leaks, etc.) COMMENT ON THEM (INSIDE THE CODE) WITH ! ALERT or TODO;
	- IDs for critical entities are UUIDs, not integer IDs (use string|int);
	- For blocks like 'if (...statement...) {...do something...}'', supress the curly brackets;
	- Pay attention to encompass methods in try/catches if some expression can throw errors that should not
			raise above the method level;
	- The creation of a method named authorize is not valid (use _authorize) instead;
	- If you write expressions that use Auth::user()->[...some function...], then call in the beginning of the method body:
			  if (
            ($userOrRedirect = self::_checkLogin())
            instanceof \Illuminate\Http\RedirectResponse
        )
            return $userOrRedirect;
        $user = $userOrRedirect;	

				++

				and implement in the beginning of the class body:

					use ChecksLogin

	- Leverage App\Traits\ChecksPermissions when you need to create guard methods for permissions:

				namespace App\Traits;

				use Illuminate\Auth\Access\AuthorizationException;
				use Illuminate\Http\{RedirectResponse, Request};

				trait ChecksPermissions
				{
					private static function guard(
						Request $req,
						string $perm,
						string $redirectRoute
					): ?RedirectResponse {
						return $req->user()->can($perm)
							? null
							: defaultPermissionDenial(
								$req,
								new AuthorizationException($perm),
								__CLASS__ . '::' . __FUNCTION__,
								route($redirectRoute)
							);
					}
				}

	- For complex methods that the type hinting does not explain what each variable does exactly,
			add PHPDocs to the function signature;
	- The import for ChecksLogin comes from App\Traits;
	- Use name spreading (with {}) for repetitive use or require calls;
	- Always prefere using foreach or Arr::only for reducing repetition of creation/updates on Models,
	    following this example:
			      foreach (['candidate', 'employee', 'date', 'time'] as $field) // repetitive pattern DRYed up by loop
            	$updateData[$field] = $data[$field]; 
            $updateData['comment'] = $request->comment ?? ''; // prop following exception rule
            $interviewSchedule->update($updateData);
	- \Validator should be replaced by Validator, and be imported from the Support Facades
	- For modules that treat financial data, always apply ACID and rollback strategies (ex.: with DB::transaction or DB::startTransaction);
